// v23.xx (gfx29), HIS ORDER (2026-10-12) on the graphics program: "add ALL of this stuff", item 12, richer ground; his answer 20 a,
// gritty and grounded like ARC Raiders. COLD STORAGE GETS ITS FLOOR. The open ground of the map was one flat colour with grime,
// so the PACKING FLOOR, CHILL ROW and the SCRAP LINE all read as the same car park. The bake now dresses the floor of COLD STORAGE
// with what a working cold store leaves on it: painted forklift lanes with stop bars and arrows down the open racking of the
// PACKING FLOOR, frost hugging the units of CHILL ROW and spreading out from the BLAST FREEZER, oil stains and tyre tracks across
// the SCRAP LINE, and drain grates on the open ground. All of it is painted once into the baked floor (no cost a frame), never
// inside a building, on a wall or in the water, and every placement is a hash of the position, so it never draws from the raid
// stream and is the same every raid. COLD STORAGE only; CFG.gfxDress 0 leaves the floor as it was.
function coldDressOpen(map,x,y,pad){
  var B=map.buildings||[], i, b;
  for(i=0;i<B.length;i++){ b=B[i]; if(x>b.x-pad&&x<b.x+b.w+pad&&y>b.y-pad&&y<b.y+b.h+pad) return false; }
  if(typeof inWaterMap==='function'&&inWaterMap(map,x,y)) return false;
  return spotFree(map,x,y,pad>4?pad:4);
}
function bakeColdDress(c,map){
  var LM={}, i, j, k, R, x, y, h, day=isDay(), B=map.buildings||[], b, x0, cx, dx, sg, n=0, fz=null;
  for(i=0;i<(map.landmarks||[]).length;i++) LM[map.landmarks[i].id]=map.landmarks[i];
  for(i=0;i<(map.locked||[]).length;i++) if(map.locked[i].id==='cs_freezer') fz=map.locked[i];
  c.save();
  try{
    c.globalAlpha=1; c.globalCompositeOperation='source-over';
    // 1. PACKING FLOOR: forklift lanes down the open racking east of the two halls, worn through in places
    R=LM.cs_pack;
    if(R){
      for(x=1110;x<R.x+R.w-80;x+=150){
        for(y=R.y+24;y<R.y+R.h-24;y+=22){
          h=grit(x*3+7,y*5+11);
          if(h<0.14||!coldDressOpen(map,x+30,y+10,8)) continue;
          c.fillStyle='rgba(224,186,62,'+((day?0.34:0.24)*(0.55+0.45*h)).toFixed(3)+')';
          c.fillRect(x-1.5,y,3,18); c.fillRect(x+58.5,y,3,18); n++;
          if(((y-R.y)%264)<22&&h>0.4){
            c.strokeStyle='rgba(232,226,210,'+(day?0.22:0.14)+')'; c.lineWidth=3;
            c.beginPath(); c.moveTo(x+20,y+4); c.lineTo(x+30,y+16); c.lineTo(x+40,y+4); c.stroke();
          }
        }
        for(k=0;k<2;k++){
          y=k?R.y+R.h-40:R.y+30;
          if(!coldDressOpen(map,x+30,y+4,8)) continue;
          for(j=0;j<60;j+=12){ c.fillStyle=((j/12)%2)?'rgba(30,28,26,.30)':'rgba(224,186,62,'+(day?0.30:0.20)+')'; c.fillRect(x+j,y,12,8); }
        }
      }
    }
    // 2. CHILL ROW and the BLAST FREEZER: frost on the ground
    R=LM.cs_chill;
    if(R){
      c.fillStyle='rgba(214,234,252,'+(day?0.13:0.08)+')';
      for(i=0;i<B.length;i++){ b=B[i];
        if(b.x<R.x-10||b.x>R.x+R.w||b.y<R.y-10||b.y>R.y+R.h) continue;
        c.fillRect(b.x-6,b.y+b.h,b.w+12,16); c.fillRect(b.x+b.w,b.y-4,14,b.h+20);
        for(j=0;j<14;j++){ h=grit(b.x+j*37,b.y+j*53);
          x=b.x+h*b.w; y=b.y+b.h+6+grit(b.x+j*11,b.y+j*7)*22;
          if(!coldDressOpen(map,x,y,2)) continue;
          c.beginPath(); c.ellipse(x,y,6+h*14,3+h*5,0,0,6.2832); c.fill(); n++; }
      }
    }
    if(fz){
      cx=fz.x+fz.w/2; dx=fz.y+fz.h/2;
      sg=c.createRadialGradient(cx,dx,fz.w*0.4,cx,dx,fz.w*1.25);
      sg.addColorStop(0,'rgba(224,240,255,'+(day?0.22:0.14)+')'); sg.addColorStop(1,'rgba(224,240,255,0)');
      c.fillStyle=sg; c.fillRect(cx-fz.w*1.3,dx-fz.h*1.3,fz.w*2.6,fz.h*2.6); n++;
    }
    // 3. SCRAP LINE: tyre tracks and oil, never inside the two sheds
    R=LM.cs_scrap;
    if(R){
      c.save();
      c.beginPath(); c.rect(R.x,R.y,R.w,R.h);
      for(i=0;i<B.length;i++){ b=B[i]; if(b.x<R.x+R.w&&b.x+b.w>R.x&&b.y<R.y+R.h&&b.y+b.h>R.y) c.rect(b.x,b.y,b.w,b.h); }
      c.clip('evenodd');
      c.strokeStyle='rgba(16,14,12,'+(day?0.18:0.22)+')'; c.lineWidth=5;
      if(c.setLineDash) c.setLineDash([7,4]);
      for(k=0;k<5;k++){
        x0=R.x+(k+0.5)*R.w/5+(grit(k*71+3,k*29+5)-0.5)*120; dx=(grit(k*13+1,k*91+7)-0.5)*260; cx=(grit(k*41+9,k*17+3)-0.5)*420;
        for(j=0;j<2;j++){ c.beginPath(); c.moveTo(x0+j*17,R.y); c.quadraticCurveTo(x0+cx+j*17,R.y+R.h*0.5,x0+dx+j*17,R.y+R.h); c.stroke(); }
        n++;
      }
      if(c.setLineDash) c.setLineDash([]);
      for(y=R.y+40;y<R.y+R.h-40;y+=90) for(x=R.x+40;x<R.x+R.w-40;x+=90){
        h=grit(x+5,y+9); if(h>0.18) continue;
        cx=x+grit(x+1,y+3)*60; dx=y+grit(x+7,y+1)*60;
        if(!coldDressOpen(map,cx,dx,4)) continue;
        c.fillStyle='rgba(8,8,10,'+(day?0.30:0.36)+')'; c.beginPath(); c.ellipse(cx,dx,10+h*60,6+h*30,0,0,6.2832); c.fill();
        c.fillStyle='rgba(70,64,120,.06)'; c.beginPath(); c.ellipse(cx-2,dx-1,6+h*40,3+h*18,0,0,6.2832); c.fill(); n++;
      }
      c.restore();
    }
    // 4. drains on the open ground
    for(y=130;y<WORLD_H-130;y+=260) for(x=130;x<WORLD_W-130;x+=260){
      h=grit(x+31,y+61); if(h>0.15) continue;
      cx=x+grit(x+3,y+5)*160; dx=y+grit(x+9,y+2)*160;
      if(!coldDressOpen(map,cx,dx,24)) continue;
      c.fillStyle='rgba(10,10,12,.14)'; c.beginPath(); c.ellipse(cx,dx+2,24,13,0,0,6.2832); c.fill();
      c.fillStyle='rgba(14,14,16,.62)'; c.fillRect(cx-9,dx-6,18,12);
      c.strokeStyle='rgba(150,156,164,'+(day?0.30:0.20)+')'; c.lineWidth=1.2; c.strokeRect(cx-9.5,dx-6.5,19,13);
      c.fillStyle='rgba(120,126,134,'+(day?0.30:0.18)+')'; for(j=0;j<4;j++) c.fillRect(cx-7+j*4.2,dx-4,1.4,8);
      n++;
    }
  } finally { c.restore(); }
  return n;
}
function bakeGround(map){

    c.fillText(String(b3.tag),b3.x+b3.w/2,b3.y+b3.h/2);
    c.restore();
  }
  if(CFG.gfxDress!==0&&map.fixed==='cold'){ try{ bakeColdDress(c,map); }catch(_bcd){} }   // v23.xx (gfx29): COLD STORAGE dressing, no seeded draw
  return g;
}

