{v:'VER',what:'graphics program gfx29: COLD STORAGE ground dressing: the baked floor with the dressing on differs from the same bake with CFG.gfxDress 0 at 300 or more sampled points inside the PACKING FLOOR, the dressing draws nothing from the raid stream, and a map that is not COLD STORAGE bakes identically either way',
 run:function(){
   if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__runPrep)||typeof bakeGround!=='function'||typeof RNGS==='undefined') return 'SKIP: this fixture cannot bake a floor';
   var bad=[], g=null, R=null, s0=RNGS, d0=CFG.gfxDress, i, A, B, n, fx0;
   function bake(dress){ var o; CFG.gfxDress=dress; try{ RNGS=s0; o={c:bakeGround(g.map)}; o.r=RNGS; } finally { CFG.gfxDress=d0; } return o; }
   function diff(a,b,x,y,w,h){
     var da=a.c.getContext('2d').getImageData(x,y,w,h).data, db=b.c.getContext('2d').getImageData(x,y,w,h).data, c2=0, q, px, py;
     for(py=0;py<h;py+=4) for(px=0;px<w;px+=4){ q=(py*w+px)*4; if(Math.abs(da[q]-db[q])>6||Math.abs(da[q+1]-db[q+1])>6||Math.abs(da[q+2]-db[q+2])>6) c2++; }
     return c2;
   }
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0);
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||g.over||!g.map) return 'SKIP: staging: no raid';
     if(g.map.fixed!=='cold') return 'SKIP: staging: map 0 is not COLD STORAGE';
     for(i=0;i<(g.map.landmarks||[]).length;i++) if(g.map.landmarks[i].id==='cs_pack') R=g.map.landmarks[i];
     if(!R) return 'SKIP: staging: COLD STORAGE has no PACKING FLOOR landmark';
     s0=RNGS;
     A=bake(undefined); B=bake(0);
     if(A.r!==B.r) bad.push('the dressing moved the raid stream');
     n=diff(A,B,R.x,R.y,R.w,R.h);
     if(n<300) bad.push('the PACKING FLOOR with the dressing differs from the bare bake at only '+n+' sampled points, not 300 or more');
     A=null; B=null;
     fx0=g.map.fixed; g.map.fixed='mile';
     try{ A=bake(undefined); B=bake(0); } finally { g.map.fixed=fx0; }
     n=diff(A,B,R.x,R.y,R.w,R.h)+diff(A,B,2240,2480,1800,840);
     if(n) bad.push('a map that is not COLD STORAGE bakes differently with the dressing on ('+n+' points)');
     A=null; B=null;
   }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
   finally{
     RNGS=s0; CFG.gfxDress=d0;
     try{ var g2=__state(); if(g2){ if(!g2.over){ g2.player.iv=0; g2.player.downed=false; __endRaid('abandon'); } } }catch(_e){}
     __topClear();
   }
   return bad.length?bad.join('; '):null; }},
